import React from 'react';
import PropTypes from 'prop-types';
import classNames from 'classnames';

import {
  WebexInMeeting,
  WebexMeetingControlBar,
  WebexDataProvider,
  MeetingContext
} from '@webex/components';

import styles from './styles.css';

// Custom controls to show screen share and other buttons
const meetingControls = (isActive) => (
  isActive
    ? ['mute-audio', 'mute-video', 'share-screen', 'member-roster', 'settings', 'leave-meeting']
    : ['mute-audio', 'mute-video', 'join-meeting']
);

// Wrapper to log what WebexMeetingControlBar receives
const DebugControlBar = (props) => {
  // eslint-disable-next-line no-console
  console.log('HELLO [DebugControlBar] Props received:', props);
  // eslint-disable-next-line no-console
  console.log('HELLO [DebugControlBar] meetingID:', props.meetingID);

  return <WebexMeetingControlBar {...props} controls={meetingControls} />;
};

DebugControlBar.propTypes = {
  meetingID: PropTypes.string.isRequired
};

const ActiveMeeting = ({setEscapedAuthentication, adapter, meetingId}) => {
  // eslint-disable-next-line no-console
  console.log('HELLO [ActiveMeeting] Rendering with meetingId:', meetingId);

  // Get the actual meeting object to verify it exists
  const meeting = adapter?.meetingsAdapter?.datasource?.meetings?.getMeetingByType('id', meetingId);

  // eslint-disable-next-line no-console
  console.log('HELLO [ActiveMeeting] meeting object:', meeting);

  // Patch the meeting controls to accept positional parameters (old API)
  // instead of object parameters (new API) to match what @webex/components expects
  React.useEffect(() => {
    if (adapter?.meetingsAdapter?.meetingControls) {
      const controls = adapter.meetingsAdapter.meetingControls;

      Object.keys(controls).forEach((key) => {
        const control = controls[key];

        if (control && control.action && !control.patchedAction) {
          const originalAction = control.action.bind(control);

          control.action = function patchedAction(meetingIDOrObject, value) {
            // If called with positional parameters (old API), convert to object (new API)
            if (typeof meetingIDOrObject === 'string') {
              return originalAction({meetingID: meetingIDOrObject, ...value});
            }

            // If already an object (new API), pass through
            return originalAction(meetingIDOrObject);
          };
          control.patchedAction = true;
        }
      });
    }
  }, [adapter]);

  // Make adapter and meeting globally accessible for debugging
  window.debugAdapter = adapter;
  window.debugMeeting = meeting;
  window.debugMeetingId = meetingId;

  if (!meetingId || !meeting) {
    // eslint-disable-next-line no-console
    console.warn('HELLO [ActiveMeeting] No valid meeting');

    return null;
  }

  return (
    <WebexDataProvider adapter={adapter}>
      <MeetingContext.Provider value={meetingId}>
        <div className={classNames(styles.callContainer, 'call-container', 'wxc-theme-light')}>
          <WebexInMeeting
            meetingID={meetingId}
            style={{flex: 1}}
            setEscapedAuthentication={setEscapedAuthentication}
          />
          <DebugControlBar
            meetingID={meetingId}
            onShareScreen={() => {
              // eslint-disable-next-line no-console
              console.log('HELLO Share screen clicked, meetingID:', meetingId);
            }}
          />
        </div>
      </MeetingContext.Provider>
    </WebexDataProvider>
  );
};

ActiveMeeting.propTypes = {
  setEscapedAuthentication: PropTypes.func,
  adapter: PropTypes.object.isRequired,
  meetingId: PropTypes.string.isRequired
};

ActiveMeeting.defaultProps = {
  setEscapedAuthentication: undefined
};

export default ActiveMeeting;
